import{_ as a,c as o,o as r,a3 as e}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/usage.md","filePath":"zh-CN/guide/usage.md","lastUpdated":1786595765000}'),l={name:"zh-CN/guide/usage.md"};function n(i,t,s,d,g,h){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to &quot;使用指南&quot;">​</a></h1><h2 id="剪贴板历史" tabindex="-1">剪贴板历史 <a class="header-anchor" href="#剪贴板历史" aria-label="Permalink to &quot;剪贴板历史&quot;">​</a></h2><p>ClipboardxAI 运行在<strong>菜单栏</strong>中。每当你复制内容时，它都会添加到历史记录。</p><ul><li>点击菜单栏图标，打开历史面板。</li><li>将鼠标悬停在某个条目上并按下操作快捷键，或点击将其复制回粘贴板。</li><li>使用搜索框，按文本查找条目。</li></ul><h2 id="ai-工具窗口" tabindex="-1">AI 工具窗口 <a class="header-anchor" href="#ai-工具窗口" aria-label="Permalink to &quot;AI 工具窗口&quot;">​</a></h2><p><strong>AI 工具（AI Tool）</strong> 窗口是操作运行的地方。它采用分栏布局：</p><ul><li><strong>左侧</strong>——工具列表，分为： <ul><li><strong>内置 AI（Built-in AI）</strong>——总结、翻译及其他 AI 操作。</li><li><strong>内置本地（Built-in Local）</strong>——离线工具（提取链接、字数统计、压缩空行）。</li><li><strong>已安装（Installed）</strong>——你从 Marketplace 添加的操作。你可以拖动以<strong>重新排序</strong>。</li></ul></li><li><strong>右侧</strong>——两个面板：一侧是<strong>原始</strong>剪贴内容，另一侧是<strong>结果</strong>。</li></ul><p>AI 工具显示「云」标识；本地工具显示「设备」标识，因此你始终清楚某项操作是否使用网络。</p><h2 id="运行操作" tabindex="-1">运行操作 <a class="header-anchor" href="#运行操作" aria-label="Permalink to &quot;运行操作&quot;">​</a></h2><ol><li>从左侧列表中选择一个工具（或接受智能建议）。</li><li>当前剪贴内容会显示在<strong>原始</strong>面板中。</li><li>结果会在<strong>结果</strong>面板中生成。</li></ol><h3 id="自动运行-auto-run" tabindex="-1">自动运行（Auto-run） <a class="header-anchor" href="#自动运行-auto-run" aria-label="Permalink to &quot;自动运行（Auto-run）&quot;">​</a></h3><p>在窗口底部打开 <strong>输出时自动运行（Auto-run on output）</strong>。启用后，只要一复制内容，所选工具就会自动运行——无需手动点击。本地工具永远不会覆盖你的粘贴板，因此自动运行是安全的。</p><h2 id="内置本地工具" tabindex="-1">内置本地工具 <a class="header-anchor" href="#内置本地工具" aria-label="Permalink to &quot;内置本地工具&quot;">​</a></h2><p>这些工具完全在 Mac 上离线运行：</p><ul><li><strong>提取链接（Extract Links）</strong>——返回文本中发现的每一个 URL。</li><li><strong>字数统计（Count Stats）</strong>——单词 / 字符 / 行数 / 句子数统计。</li><li><strong>压缩空行（Collapse Blank Lines）</strong>——移除粘贴文本中的空行。</li></ul><h2 id="云端-ai-设置" tabindex="-1">云端 AI 设置 <a class="header-anchor" href="#云端-ai-设置" aria-label="Permalink to &quot;云端 AI 设置&quot;">​</a></h2><p>要使用 AI 操作，请在 <strong>设置 → AI（Settings → AI）</strong> 中连接一个提供商：</p><ol><li>选择提供商——<strong>DeepSeek</strong>、<strong>MiniMax</strong>、<strong>Zhipu GLM</strong>、<strong>Kimi (Moonshot)</strong>、<strong>Mistral</strong>、<strong>Ollama</strong>（本地），或其他 OpenAI 兼容服务。</li><li>粘贴你的 <strong>API key</strong>。它保存在 <strong>Keychain</strong> 中，绝不会以明文写入磁盘。</li><li>选择一个模型。</li><li>云端 AI 默认关闭。启用后，你的剪贴内容只会发送给所配置的提供商。</li></ol><p>如果未设置 key，配置横幅会在 AI 工具窗口中提醒你。</p><h2 id="操作市场-marketplace" tabindex="-1">操作市场（Marketplace） <a class="header-anchor" href="#操作市场-marketplace" aria-label="Permalink to &quot;操作市场（Marketplace）&quot;">​</a></h2><ol><li>从 AI 工具窗口打开 <strong>Marketplace</strong>（或站点的 <a href="/zh-CN/marketplace/">Marketplace</a> 页面）。</li><li>在某个操作上点击 <strong>安装（Install）</strong>。这会通过深链接 <code>clipboardxai://install?action=&lt;id&gt;</code> 打开应用，并将该操作添加到你的 <strong>已安装（Installed）</strong> 列表。</li></ol><h2 id="键盘快捷键" tabindex="-1">键盘快捷键 <a class="header-anchor" href="#键盘快捷键" aria-label="Permalink to &quot;键盘快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>操作</th></tr></thead><tbody><tr><td><code>Cmd+Shift+V</code></td><td>打开剪贴板历史</td></tr><tr><td><code>Cmd+,</code></td><td>打开设置</td></tr><tr><td><code>Cmd+W</code></td><td>关闭窗口</td></tr><tr><td><code>Cmd+Q</code></td><td>退出应用</td></tr></tbody></table><blockquote><p>具体快捷键可能因版本而异；请在应用内的 <strong>设置 → 快捷键（Settings → Shortcuts）</strong> 中查看。</p></blockquote><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h2><p>打开 <strong>ClipboardxAI → 设置（Settings）</strong>（或按 <code>Cmd+,</code>）：</p><ul><li><strong>通用（General）</strong>：语言、登录时启动、外观主题。</li><li><strong>AI</strong>：云端提供商、模型与 API key（Keychain）。</li><li><strong>操作（Actions）</strong>：自动运行开关、排除的应用、工具顺序。</li><li><strong>隐私（Privacy）</strong>：云端 AI 选择性开启、排除的应用、历史记录控制。</li><li><strong>Marketplace</strong>：浏览并管理已安装的操作。</li></ul>',27)])])}const p=a(l,[["render",n]]);export{u as __pageData,p as default};
